const fs=require('fs');
const path=require('path');
const cp=require('child_process');
const {chromium}=require('@playwright/test');

const TARGET='assets/css/pages/chat-workspace-layout-contract.css';
const TARGET_SHA=process.env.TARGET_SHA;
const TARGET_BLOB=process.env.TARGET_BLOB;
const PAGES=[
  {page:'mensagens.html',foundation:'assets/css/pages/messaging-foundation.css',runtime:'assets/css/pages/messaging-runtime-chat.css',kind:'messages'},
  {page:'comunidade-interna.html',foundation:'assets/css/pages/comunidade-interna-foundation.css',runtime:'assets/css/pages/comunidade-interna-runtime-chat.css',kind:'community'}
];
const MANIFEST='assets/css/pages/chat-workspace-foundation.css';
const VIEWPORTS=[359,430,759,760,1022,1023,1024,1025,1180,1280,1440];
const STATES=['closed','open'];
const sh=cmd=>cp.execSync(cmd,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const assert=(ok,msg)=>{if(!ok)throw new Error(msg);};

function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v);}return out;}
function verifyReach(){const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8'));const tracked=new Set(sh('git ls-files -z assets/css').split('\0').filter(f=>f.endsWith('.css')));const direct=[...tracked].filter(f=>importsFor(f,tracked).includes(TARGET)).sort();assert(JSON.stringify(direct)==JSON.stringify([MANIFEST]),`direct importer drift ${JSON.stringify(direct)}`);for(const p of PAGES){assert(importsFor(p.foundation,tracked).includes(p.runtime),`${p.page} foundation runtime drift`);assert(importsFor(p.runtime,tracked).includes(MANIFEST),`${p.page} runtime manifest drift`);assert(importsFor(MANIFEST,tracked).includes(TARGET),'manifest target missing');const html=fs.readFileSync(p.page,'utf8'),base=path.posix.basename(p.foundation).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');assert((html.match(new RegExp(`assets/css/pages/${base}\\?v=`,'g'))||[]).length===1,`${p.page} foundation link drift`);}const reached=[];for(const p of report.pageAssets){const seen=new Set(),stack=[...(p.css||[]).filter(f=>tracked.has(f))];let hit=false;while(stack.length){const f=stack.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break;}for(const n of importsFor(f,tracked))stack.push(n);}if(hit)reached.push(p.page);}assert(JSON.stringify(reached.sort())===JSON.stringify(PAGES.map(p=>p.page).sort()),`active reach drift ${JSON.stringify(reached)}`);console.log(`STATIC REACH PASS|pages=${reached.sort().join(',')}|directImporter=${MANIFEST}|runtimes=${PAGES.map(p=>p.runtime).join(',')}|target=${TARGET}`);}
function verifyDead(parsed){assert(parsed.declarations.length===754,`declaration drift ${parsed.declarations.length}`);assert(parsed.dead.length===27,`dead drift ${parsed.dead.length}`);const families=new Set(parsed.dead.map(d=>d.selector));assert(families.size===8,`family drift ${families.size}`);const expectedFamilies=new Set([
'body:is([data-page="mensagens"], [data-page="comunidade-interna"]) .messages-shell-content, body[data-page="comunidade-interna"] .community-room-shell',
'body:is([data-page="mensagens"], [data-page="comunidade-interna"]) .messages-app',
'body[data-page="comunidade-interna"] .community-room-layout',
'body:is([data-page="mensagens"], [data-page="comunidade-interna"])',
'body:is([data-page="mensagens"], [data-page="comunidade-interna"]) :is(.messages-composer, .community-room-composer)',
'body:is([data-page="mensagens"], [data-page="comunidade-interna"]) .messages-sidebar',
'body:is([data-page="mensagens"], [data-page="comunidade-interna"]) :is(.messages-list, .community-room-channel-list, .community-room-online-list)',
'body:is([data-page="mensagens"], [data-page="comunidade-interna"]) :is(.messages-block, .community-room-block)'
]);
for(const f of expectedFamilies)assert(families.has(f),`missing family ${f}`);const contexts={global:0,max1023:0,min1024:0};for(const d of parsed.dead){if(d.context==='')contexts.global++;else if(d.context==='@media (max-width: 1023px)')contexts.max1023++;else if(d.context==='@media (min-width: 1024px)')contexts.min1024++;else throw new Error(`unexpected context ${d.context}`);assert(d.winnerLine>d.line,`winner order ${d.line}`);assert(!d.important&&!d.winnerImportant,`important drift ${d.line}`);}assert(contexts.global===15&&contexts.max1023===4&&contexts.min1024===8,`context counts ${JSON.stringify(contexts)}`);const identical=parsed.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===13,`identical drift ${identical}`);assert(parsed.dead.length-identical===14,`changed drift ${parsed.dead.length-identical}`);console.log(`DEAD ROWS PASS|decl=754|dead=27|families=8|identical=13|changed=14|contexts=global15,max1023=4,min1024=8|lines=${parsed.dead.map(d=>d.line).join(',')}`);}
function removeDead(parsed){const src=fs.readFileSync(TARGET,'utf8'),finalNewline=/\r?\n$/.test(src);const lines=src.split(/\r?\n/);if(finalNewline&&lines.at(-1)==='')lines.pop();for(const d of [...parsed.dead].sort((a,b)=>b.line-a.line)){const line=lines[d.line-1];assert(line&&line.trim().startsWith(`${d.property}:`),`line mismatch ${d.line}: ${line}`);lines.splice(d.line-1,1);}fs.writeFileSync(TARGET,lines.join('\n')+(finalNewline?'\n':''));const stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(stat[0]==='0'&&stat[1]==='27'&&stat[2]===TARGET,`unexpected diff ${stat.join(' ')}`);const after=parse(fs.readFileSync(TARGET,'utf8'));assert(after.declarations.length===727,`after declarations ${after.declarations.length}`);assert(after.dead.length===0,`after dead ${after.dead.length}`);console.log('EPHEMERAL DELTA PASS|file=chat-workspace-layout-contract.css|additions=0|deletions=27|decl=754->727|dead=27->0');}
async function prepare(page,spec,state){await page.evaluate(({kind,state})=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.documentElement.classList.remove('doke-mobile-shell-pending');document.documentElement.classList.toggle('chat-room-mobile-open',state==='open');if(kind==='messages'){document.body.dataset.page='mensagens';const root=document.querySelector('[data-messages-page]');if(root){root.removeAttribute('aria-busy');root.dataset.viewState='ready';root.hidden=false;}const skeleton=document.querySelector('[data-messages-hydration-skeleton]');if(skeleton)skeleton.hidden=true;document.querySelectorAll('[data-messages-hydration-ready]').forEach(el=>el.hidden=false);document.querySelector('.messages-sidebar')?.removeAttribute('hidden');document.querySelector('.messages-thread')?.removeAttribute('hidden');}else{document.body.dataset.page='comunidade-interna';const pending=document.querySelector('[data-community-room-pending]');if(pending)pending.hidden=true;const root=document.querySelector('[data-community-room]');if(root)root.hidden=false;document.querySelector('.community-room-sidebar')?.removeAttribute('hidden');document.querySelector('.community-room-thread')?.removeAttribute('hidden');}}, {kind:spec.kind,state});}
async function captureOne(page,spec,state){return page.evaluate(({kind,state})=>{const round=n=>Math.round(n*1000)/1000;const pick=(sel)=>{const el=document.querySelector(sel);if(!el)return null;const s=getComputedStyle(el),r=el.getBoundingClientRect();return{display:s.display,width:s.width,maxWidth:s.maxWidth,minWidth:s.minWidth,height:s.height,minHeight:s.minHeight,maxHeight:s.maxHeight,gridTemplateColumns:s.gridTemplateColumns,alignContent:s.alignContent,alignItems:s.alignItems,gap:s.gap,overflow:s.overflow,overflowX:s.overflowX,overflowY:s.overflowY,marginInline:s.marginInline,padding:s.padding,border:s.border,borderRadius:s.borderRadius,backgroundImage:s.backgroundImage,backgroundColor:s.backgroundColor,boxShadow:s.boxShadow,rect:[round(r.x),round(r.y),round(r.width),round(r.height)]};};const shell=kind==='messages'?'.messages-shell-content':'.community-room-shell';const app=kind==='messages'?'.messages-app':'.community-room-layout';const sidebar=kind==='messages'?'.messages-sidebar':'.community-room-sidebar';const list=kind==='messages'?'.messages-list':'.community-room-channel-list';const block=kind==='messages'?'.messages-block':'.community-room-block';const composer=kind==='messages'?'.messages-composer':'.community-room-composer';const bodyStyle=getComputedStyle(document.body);return{page:kind==='messages'?'mensagens.html':'comunidade-interna.html',state,rootVars:{rail:bodyStyle.getPropertyValue('--chat-rail-max').trim(),desktopHeight:bodyStyle.getPropertyValue('--chat-desktop-height').trim(),sidebarWidth:bodyStyle.getPropertyValue('--chat-sidebar-desktop-width').trim()},pageContent:pick('.page__content'),shell:pick(shell),app:pick(app),sidebar:pick(sidebar),list:pick(list),block:pick(block),composer:pick(composer),doc:{clientWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,bodyScrollWidth:document.body.scrollWidth}};},{kind:spec.kind,state});}
async function capture(browser,tag){const out={};let samples=0;for(const spec of PAGES){for(const state of STATES){for(const width of VIEWPORTS){const context=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'});const page=await context.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url());const local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort();});await page.goto(`http://127.0.0.1:4173/${spec.page}?ux044-${tag}-${state}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});await prepare(page,spec,state);await page.waitForTimeout(35);const snap=await captureOne(page,spec,state);assert(snap.doc.scrollWidth<=snap.doc.clientWidth+1,`horizontal overflow ${tag} ${spec.page} ${state} ${width} ${JSON.stringify(snap.doc)}`);out[`${spec.page}:${state}:${width}`]=snap;samples++;await context.close();}}}console.log(`RUNTIME CAPTURE|tag=${tag}|pages=2|states=${STATES.length}|viewports=${VIEWPORTS.join(',')}|samples=${samples}|overflow=0`);return out;}
(async()=>{assert(TARGET_SHA&&TARGET_BLOB,'missing env');assert(sh('git rev-parse HEAD')===TARGET_SHA,'wrong HEAD');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');verifyReach();const parsed=parse(fs.readFileSync(TARGET,'utf8'));verifyDead(parsed);const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');console.log(`CASCADE RUNTIME PARITY PASS|runtimeDiffs=0|overflow=0|families=8/8|reachPages=2|states=2|viewports=${VIEWPORTS.length}|samples=${Object.keys(before).length}|boundary=1022/1023/1024/1025|staticCascadeRows=27|identicalWinners=13|changedWinners=14`);}finally{await browser.close();}}finally{server.kill('SIGTERM');}sh(`git reset --hard ${TARGET_SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===TARGET_SHA,'restore HEAD drift');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'restore blob drift');assert(sh('git status --porcelain')==='','restore dirty');console.log(`CHECKPOINT PASS|sha=${TARGET_SHA}|productMutation=0|issueCreated=0|prCreated=0`);})().catch(e=>{console.error(e.stack||e);process.exit(1);});
